export interface ProcResult {
  key: string;
  payload: number;
  processedAt: number;
}

export class Processor {
  effects: [string, number][] = [];
  private seen = new Map<string, ProcResult>();

  constructor(private window: number) {}

  process(key: string, payload: number, now: number): ProcResult {
    const cached = this.seen.get(key);
    if (cached !== undefined) {
      return cached;
    }
    this.effects.push([key, payload]);
    const result = { key, payload, processedAt: now };
    this.seen.set(key, result);
    return result;
  }
}

