const assert = require("assert");
const { Processor } = require("./build/processor.js");

{
  const p = new Processor(10);
  const first = p.process("order-1", 5, 0);
  const second = p.process("order-1", 999, 5);
  assert.deepStrictEqual(second, first);
  assert.strictEqual(p.effects.length, 1);
}
{
  const p = new Processor(10);
  p.process("a", 1, 0);
  p.process("b", 2, 0);
  assert.strictEqual(p.effects.length, 2);
}
{
  const p = new Processor(10);
  p.process("order-1", 5, 0);
  p.process("order-1", 5, 9);
  assert.strictEqual(p.effects.length, 1);
  p.process("order-1", 7, 10);
  assert.strictEqual(p.effects.length, 2);
  assert.deepStrictEqual(p.effects[1], ["order-1", 7]);
}
console.log("behavior OK");
